//! Golden numerators/denominators generated by Python Rational(str(float(x))).
use cftuv_angular::{decimal_text_to_rat, DecimalTextDecline as D, MAX_DECIMAL_TEXT_BYTES};
use cftuv_core::{num::{IBig, UBig}, rat::Rat};
#[test]
fn python_binary64_text_goldens_are_exact_and_canonical() {
    let data=include_str!("decimal_float_golden.tsv");
    assert_eq!(data.lines().count(),24);
    for line in data.lines() {
        let parts:Vec<_>=line.split('\t').collect();assert_eq!(parts.len(),3);
        let got=decimal_text_to_rat(parts[0]).unwrap();
        assert_eq!(got.numerator(),&IBig::from_str_radix(parts[1],10).unwrap(),"{}",parts[0]);
        assert_eq!(got.denominator(),&UBig::from_str_radix(parts[2],10).unwrap(),"{}",parts[0]);
        assert!(Rat::is_canonical(got.numerator(),got.denominator()));
    }
    assert_eq!(decimal_text_to_rat("0.1").unwrap(),Rat::new(IBig::from(1),IBig::from(10)).unwrap());
}
#[test]
fn zeros_and_decimal_scientific_spellings() {
    for text in ["0","-0","+0.0","-0.000e+99","0e-1024"] {
        assert_eq!(decimal_text_to_rat(text),Ok(Rat::zero()),"{text}");
    }
    for text in ["1.25","125e-2","+1.2500E+0",".125e1","1250.e-3"] {
        assert_eq!(decimal_text_to_rat(text),Ok(Rat::new(IBig::from(5),IBig::from(4)).unwrap()),"{text}");
    }
}
#[test]
fn named_declines_for_nonfinite_and_non_decimal_text() {
    for text in ["nan","-nan","inf","-inf","+Infinity"] {assert_eq!(decimal_text_to_rat(text),Err(D::NonFinite),"{text}");}
    for text in [""," "," 1","1 ","1\n",".","+","--1","1..2","1e","1e+","1e2e3","1/2","0x1","1_000","١.٢"] {
        assert_eq!(decimal_text_to_rat(text),Err(D::InvalidDecimal),"{text:?}");
    }
}
#[test]
fn bounded_work_is_a_named_decline_not_float_overflow() {
    assert_eq!(decimal_text_to_rat(&"1".repeat(MAX_DECIMAL_TEXT_BYTES+1)),Err(D::InputTooLong));
    for text in ["1e1025","1e-1025","1e999999999999999999","0e999999999999999999"] {
        assert_eq!(decimal_text_to_rat(text),Err(D::ExponentOutOfRange),"{text}");
    }
    assert_eq!(decimal_text_to_rat("0.1e-1024"),Err(D::ScaleOutOfRange));
    for text in ["1e1024","1e-1024"] { assert!(decimal_text_to_rat(text).is_ok()); }
}
